'QZ_Tray_Printer' => 'QZ Tray (printer na kọmputa a)',
'QZ_Printer_Name_Hint' => 'Aha printer dịka ọ pụtara na kọmputa na-agba QZ Tray. Hapụ ya efu iji jiri printer ndabara kọmputa ahụ. Pịa ⟳ iji chọpụta printer.',
'QZ_Not_Running' => 'QZ Tray anaghị agba na kọmputa a. Tinye ya site na qz.io ma hapụ ya ka ọ na-agba, wee kwe ka weebụsaịtị a rụọ ọrụ mgbe QZ jụrụ.',
'Detect_Printers' => 'Chọpụta printer',
'QZ_Download_Cert' => 'Budata asambodo (override.crt)',
'QZ_Setup_Title' => 'Otu e si edozi mbipụta QZ Tray (otu ugboro, na kọmputa ọ bụla na-ebipụta labelụ)',
'QZ_Step_Install' => '1. Tinye QZ Tray na kọmputa a — budata ya n\'efu site na qz.io, wee malite ya ma hapụ ya ka ọ na-agba (ọ na-anọ na system tray na Windows ma ọ bụ na menu bar na macOS).',
'QZ_Step_Connect' => '2. Jikọọ printer labelụ gị site na USB ma lelee na etinyere ya na sistemụ arụmọrụ (Windows: Settings > Printers & scanners — macOS: System Settings > Printers & Scanners).',
'QZ_Step_Detect' => '3. Pịa bọtịnụ ⟳ dị n\'akụkụ "Aha printer" n\'elu iji chọpụta printer dị na kọmputa a, wee họrọ printer labelụ gị. Hapụ mpaghara ahụ efu iji jiri printer ndabara kọmputa ahụ.',
'QZ_Step_Cert' => '4. Maka mbipụta na-enweghị popup ikike, budata asambodo dị n\'okpuru ma detuo ya n\'ime folda nhazi QZ Tray, gbanwee aha ya ka ọ bụrụ override.crt (Windows: C:\\Program Files\\QZ Tray — macOS: /Applications/QZ Tray.app/Contents/Resources — Linux: /opt/qz-tray). Wee mechie QZ Tray ma malite ya ọzọ.',
'QZ_Step_Test' => '5. Pịa "Bipụta labelụ nnwale" n\'okpuru. Ọ bụrụ na QZ Tray arịọ ikike, pịa Allow — mgbe etinyere asambodo ahụ, ọ gaghị arịọ ọzọ.',
'QZ_Step_Save' => '6. Pịa Zipu iji chekwaa ntọala ndị a. Labelụ site n\'ibe Bipụta Barcode ga-ebipụta ozugbo na printer a, na-enweghị windo mbipụta ihe nchọgharị.',
'QZ_Setup_Note' => 'QZ Tray na-agba na kọmputa ị na-eji achọgharị, ya mere nke a na-arụ ọrụ ọbụna mgbe Stocky dị na sava dị anya. Kọmputa ọ bụla na-ebipụta labelụ chọrọ ka etinye QZ Tray.',

