'Ord_Guide_MarkPaid_Note' => 'Ọnọdụ Ịkwụ Ụgwọ e gosiri ebe a na-aga n\'ihu na-edekọ nhọrọ ịkwụ ụgwọ ma na-anọ otu ahụ. Ọrịre ahụ bụ ndekọ ego, ọ bụkwa ya na-enye akụkọ ịkwụ ụgwọ na uru gị. Jiri Gosi Ịkwụ Ụgwọ n\'ọrịre ahụ iji nyochaa ma ọ bụ dezie ihe i tinyere.',
'Ord_Guide_Notes_Title' => 'Ihe Dị Mma Ịmara',
'Ord_Guide_Note_Warehouse' => 'Ụlọ nkwakọba ị họrọrọ mgbe ị na-akwado na-ekpebi ebe a ga-ewepụ ngwaahịa dị. Ụlọ nkwakọba na-enweghị ike ikpuchi iwu niile ka akaara Agwụla na ndepụta ahụ.',
'Ord_Guide_Note_Preorder' => 'Ngwa iwu tupu oge na-agafe nlele ngwaahịa dị, ya mere enwere ike ịkwado iwu nwere ha ọbụna mgbe ọnụọgụ ahụ adịbeghị n\'aka.',
