'VG_Opt_Step2' => 'Dee aha nhọrọ dịka Agba ma ọ bụ Nha, ma ọ bụ họrọ otu n\'ime ntụaro ndị ahụ.',
'VG_Opt_Step3' => 'Dee uru (dịka Uhie) ma pịa Enter. Megharịa maka uru ọ bụla; rịkọm na-ekewakwa uru. Pịa x n\'uru iji wepụ ya.',
'VG_Opt_Step4' => 'Pịa "Tinye nhọrọ" maka nhọrọ nke abụọ ma ọ bụ nke atọ (nhọrọ 3 kachasị).',
'VG_Opt_Step5' => 'Pịa "Mepụta ụdị". A na-emepụta otu ahịrị kwa ngwakọta ma wuo aha ya na-akpaghị aka, dịka "Red / S".',
'VG_Opt_Step6' => 'Tinye ọnụ ego na ọnụahịa n\'ahịrị ọ bụla, ma ọ bụ dee uru na "Tinye na ha niile" ma pịa Ọnụ Ego ma ọ bụ Ọnụahịa iji detuo ya n\'ahịrị ọ bụla.',
'VG_Opt_Step7' => 'A na-emepụtara gị koodu. Dee nke gị ma ọ bụ pịa akara ngosi mmezigharị iji mepụta ọzọ.',
'VG_Opt_Step8' => 'Nhọrọ: kaa akara "Swatch agba" na nhọrọ ma họrọ agba maka uru ọ bụla; ụlọ ahịa na-egosi ya dịka ntụpọ nwere agba.',
'VG_Rows_Title' => 'Ahịrị ụdị',
'VG_Rows_Text' => 'Ahịrị ọ bụla nwere onyonyo, koodu, barcode, ọnụ ego, ọnụahịa, ọnụahịa ọkọhọ na ọnụahịa ire kacha nta. Mgbe ị na-emepụta ngwaahịa, ị nwekwara ike itinye ngwaahịa mbido kwa ụlọ nkwakọba maka ụdị ọ bụla. Tag "Ezughị ezu" pụtara na ahịrị ahụ enweghị uru maka otu nhọrọ.',
'VG_List_Title' => 'Ọnọdụ ndepụta dị mfe',
'VG_List_Text' => 'Dee aha ụdị ma pịa Enter (ma ọ bụ pịa Tinye) iji gbakwunye ahịrị, wee dejupụta koodu na ọnụahịa ya. Nke a bụ omume ochie ma ọ na-adịgide maka ngwaahịa dị adị.',
'VG_Edit_Title' => 'Idezi ma emechaa',
'VG_Edit_1' => 'Tinye uru ma pịa "Mepụta ụdị": naanị ngwakọta ndị na-efu ka a na-etinye. Ahịrị dị adị na-edobe koodu, ọnụahịa na akụkọ ha.',
'VG_Edit_2' => 'Iwepụ uru ma ọ bụ nhọrọ na-ewepụ ahịrị ndị na-eji ya. A na-ehichapụ ahịrị echekwaralarị mgbe i chekwara ngwaahịa ahụ, mgbe nkwado gasịrị.',
'VG_Edit_3' => 'Enweghị ike iwepụ ụdị ka nwere ngwaahịa dị. Buru ụzọ dozie ma ọ bụ bufee ngwaahịa ya.',
'VG_Edit_4' => 'Ịgbanwe gaa na "Ndepụta dị mfe" na-edobe ahịrị na aha ha mana na-atụfu nkọwa nhọrọ.',
'VG_Store_Title' => 'N\'ụlọ ahịa ịntanetị',
'VG_Store_Text' => 'Ndị ahịa na-ahọrọ otu uru kwa nhọrọ, dịka Agba wee Nha. A na-agbanyụ ngwakọta na-adịghị adị, a na-adọkwa ahịrị gafee ndị agwụla. Ụdị ahọrọ bụ ihe na-aga n\'ụgbọ.',
