'Warehouse_Invoice_Address_Help' => 'Adreesị okporo ụzọ e bipụtara n\'akwụkwọ ụgwọ ụlọ nkwakọba a nyere. Hapụ ya efu iji jiri adreesị ụlọ ọrụ site na ntọala.',
'Warehouse_Logo_Help' => 'Logo e bipụtara n\'akwụkwọ ụgwọ na rịsịt POS ụlọ nkwakọba a. Hapụ ya efu iji jiri logo ụlọ ọrụ.',
'Warehouse_Invoice_Footer_Help' => 'Ndetu ọzọ e bipụtara n\'ala akwụkwọ ụgwọ ụlọ nkwakọba a nyere.',
'Issued_By' => 'Onye Nyere Ya',
