'Enable_Warehouse_Letterhead_Hint' => 'Bipụta ụlọ nkwakọba nyere ya n\'akwụkwọ ụgwọ, rịsịt POS na ibe akwụkwọ ụgwọ ọha: aha ya na-anọchi aha ụlọ ọrụ, adreesị, ekwentị, email, logo na ndetu ala ibe ya na-anọchikwa nke ụlọ ọrụ. Mpaghara ọ bụla a hapụrụ efu n\'ụlọ nkwakọba na-alaghachi na ntọala ụlọ ọrụ zuru oke.',
