'Upd_Guide_Before_Title' => '1. Tupu imelite',
'Upd_Guide_Before_Download' => 'Budata {package} nke ngwa ahụ site n\'akaụntụ CodeCanyon gị ({path}). Ewepụtala ya — ihe mmelite chọrọ ZIP ahụ kpọmkwem otu e si budata ya.',
