'Upd_Guide_Before_Quiet' => 'Họrọ oge dị jụụ: n\'oge mmelite, ngwa ahụ na-aba n\'ọnọdụ nlekọta nwa oge, a na-akpọchikwa ndị ọrụ ndị ọzọ.',
