'Upd_Not' => 'Ọ dịghị mkpa',
'Upd_Guide_Code_Overwritten' => 'Ọ bụrụ na i ji aka gbanwee koodu ngwa ahụ, mmelite ahụ ga-edegharị mgbanwe gị. A na-echekwa data gị, ihe ebulitere, ntọala na .env mgbe niile.',
