'Upd_Guide_Run_Open' => 'Mepee {path} (peeji a) ma nọrọ na taabụ {tab}.',
'Upd_Guide_Run_Upload' => '{upload}: pịa ma ọ bụ dọrọ ngwugwu ebudatara n\'ime igbe mbulite. A na-ebulite faịlụ buru ibu n\'obere iberibe, ya mere nke a na-arụkwa ọrụ na hosting ekerịtara nwere oke mbulite dị ala. Checksum na-eche nche megide mbulite mebiri emebi ma ọ bụ ezughị ezu.',
'Upd_Upload_The_Zip' => 'Bulite ZIP ahụ',
'Upd_Guide_Run_Validation' => '{auto} mgbe mbulite gasịrị (ị nwere ike ịgba ya ọzọ site na bọtịnụ {button}). Sistemụ na-enyocha: izu oke ZIP, nhazi na izu oke ngwugwu, ndakọrịta ụdị (a na-ajụ ịlaghachi azụ), ụdị PHP na extension a chọrọ, ikike faịlụ, ohere disk efu, njikọ database, nhazi, na na ọ dịghị mmelite ọzọ na-aga.',
'Upd_Validation_Runs_Automatically' => 'Nkwado na-agba na-akpaghị aka',
'Upd_Guide_Run_Review' => 'Nyochaa panel {panel}. Bọtịnụ {button} na-apụta naanị mgbe nlele dị mkpa ọ bụla gafere. Ọ bụrụ na nlele dara, ozi ahụ na-agwa gị kpọmkwem ihe ị ga-edozi.',
'Upd_Guide_Run_Click' => 'Pịa {button} ma kwado. Wee {keep} ma lee ogwe ọganihu. Sistemụ na-eme, n\'usoro:',
'Upd_Keep_Page_Open' => 'hapụ peeji a ka ọ meghee',
'Upd_Guide_Phase_Backup' => '{label} — a na-emepụta ma {verified} mbupụ database zuru ezu, ZIP nke faịlụ ngwa ọ bụla mmelite nwere ike ịgbanwe, na mbipụta nke {env}. Mmelite anaghị emetụ ihe ebulitere gị ({images}) na {storage} aka, ya mere a naghị echekwa ha. Ọ bụrụ na a pụghị ịmepụta backup, mmelite na-akwụsị ebe a, ọ dịghịkwa ihe gbanwere.',
'Upd_Verified' => 'nyochaa',
'Upd_Guide_Phase_Prepare' => '{label} — a na-ewepụta ụdị ọhụrụ n\'ebe nkwadebe ma nyochaa ya ọzọ. Ngwa dị ndụ ka anaghị emetụ aka.',
'Upd_Guide_Phase_Maintenance' => '{label} — a na-agbanye ọnọdụ nlekọta; ndị ọbịa na-ahụ ihuenyo "Anyị ga-alọta ozugbo" dị mma.',
'Upd_Guide_Phase_Files' => '{label} — a na-agbanwe faịlụ ọhụrụ n\'ime ozugbo; a na-edebe faịlụ ochie n\'akụkụ maka nlaghachi. A naghị edochi ụzọ echekwara ({env}, {storage}, {images}).',
'Upd_Guide_Phase_Database' => '{label} — migration na-agba, wee mee ka ikike, ntụgharị na templeeti dị ọhụrụ.',
'Upd_Guide_Phase_Cache' => '{label} — a na-ekpochapụ ma wughachi cache niile.',
