'Upd_Guide_Phase_Done' => '{label} — a na-ewepụ ọnọdụ nlekọta ma hichaa faịlụ nwa oge.',
'Upd_Guide_Run_Success' => 'Mgbe ị hụrụ {success}, pịa {reload} ma mee ka ihe nchọgharị gị dị ọhụrụ kpamkpam ({keys}) ka asset panel nchịkwa ọhụrụ buli.',
'Upd_Update_Successful_Short' => 'Mmelite gara nke ọma',
'Upd_Guide_No_Internet' => 'Achọghị njikọ ịntanetị n\'oge mmelite — ihe niile si na ZIP ebulitere. Ịtụfu njikọ gị ma ọ bụ imechi ihe nchọgharị anaghị emebi mmelite: sava na-echeta kpọmkwem ebe ọ kwụsịrị.',
'Upd_Guide_Wrong_Title' => '3. Ọ bụrụ na ihe adịghị mma',
'Upd_Guide_Wrong_Rollback' => '{label} — ọ bụrụ na ihe ọ bụla dara mgbe faịlụ malitere ịgbanwe (njehie mwepụta, ọdịda migration, nlele ahụike dara, disk juru, …), sistemụ na-eweghachi faịlụ gara aga na database site na backup enyochara na-akpaghị aka, wepụ ọnọdụ nlekọta, ma kọọ {message}. Ị na-alaghachi kpọmkwem ebe ị malitere.',
