'Upd_Guide_Wrong_Interrupted' => '{label} (mmalitegharị sava, oge gwụrụ, ihe nchọgharị mechiri emechi, ọkụ gbanyụrụ) — mgbe i megheghachiri peeji a, ọkọlọtọ uhie na-enye nhọrọ abụọ dị mma: {resume} (na-amalitegharị site na nzọụkwụ kpọmkwem ebe ọ kwụsịrị) ma ọ bụ {rollback} (na-eweghachi ụdị gara aga site na backup).',
'Upd_Interrupted_Update' => 'Mmelite e kwụsịrị',
'Upd_Guide_Wrong_Unreachable' => '{label} — jiri {console} kwụ onwe ya na {path}. Ọ na-arụ ọrụ ọbụna mgbe saịtị nọ n\'ọnọdụ nlekọta ma ọ bụ asset panel nchịkwa mebiri emebi, ma na-enye otu omume Gaa n\'ihu / Laghachi azụ. E nwekwara njikọ "Nnweta onye nchịkwa" zoro ezo na ala ihuenyo nlekọta.',
'Upd_Admin_Unreachable' => 'Enweghị ike iru panel nchịkwa',
'Upd_Recovery_Console' => 'console mgbake',
'Upd_Guide_Wrong_Locked_Out' => '{label} — mgbe mmelite na-aga, peeji a na-egosi {link}. Chekwaa ya ma ọ bụrụ na ịchọrọ ịlaghachi (dịka mgbe nnọkọ gị gwụrụ); ọ na-ekwe ka i gafee ihuenyo nlekọta ka i nwee ike ịbanye ọzọ.',
'Upd_Locked_Out_Maintenance' => 'Ọnọdụ nlekọta kpọchiri gị n\'èzí',
'Upd_Bypass_Link' => 'njikọ ngafe',
'Upd_Guide_Wrong_Concurrent' => '{label} — ha ga-ahụ {message} Ọ bụ naanị otu mmelite nwere ike ịgba n\'otu oge.',
'Upd_Another_Admin_Updating' => 'Onye nchịkwa ọzọ na-anwa imelite n\'otu oge',
'Upd_Guide_Backups_Title' => '4. Backup & mweghachi',
'Upd_Guide_Backups_Created' => 'Mmelite ọ bụla na-emepụta backup {before} ya emetụ ihe ọ bụla aka: faịlụ ngwa niile mmelite nwere ike idochi, mbipụta nke {env}, na mbupụ database zuru ezu. Mmelite anaghị agbanwe ihe ebulitere na {storage}, ya mere ha anọghị na ya — debe backup nke gị maka ha. Backup na-adị na {path}, a pụghịkwa ịnweta ha site na weebụ.',
'Upd_Before' => 'tupu',
'Upd_Guide_Backups_Panel' => 'Panel {panel} na taabụ {tab} na-edepụta ha ya na ụbọchị, ụdị na nha. Site n\'ebe ahụ ị nwere ike {restore} backup ọ bụla zuru ezu (faịlụ + database — a na-ebu ụzọ were mbipụta nchekwa nke database ugbu a) ma ọ bụ {delete} ndị ochie.',
'Upd_Restore_Verb' => 'weghachi',
'Upd_Delete_Verb' => 'hichapụ',
'Upd_Guide_Backups_Retention' => 'Jiri {keep} họrọ ọnụọgụ backup a ga-edebe; a na-ewepụ ndị ochie na-akpaghị aka mgbe mmelite ọ bụla gara nke ọma. A pụghị ihichapụ naanị backup zuru ezu fọdụrụ — ị na-enwe ụzọ nlaghachi mgbe niile.',
'Upd_Guide_Manual_Title' => '5. Mmelite n\'aka (ụzọ ndabere)',
'Upd_Guide_Manual_Text' => 'Ọ bụrụ na ịhọrọ imelite n\'aka, ma ọ bụ na a pụghị iji ihe mbulite na sava gị, soro ntuziaka nzọụkwụ n\'nzọụkwụ na taabụ {tab} nke peeji a.',
'Upd_Guide_Clear_Cache_First' => 'Ọ bụrụ na peeji yiri ka ha mebiri emebi ma ọ bụ tọgbọrọ chakoo mgbe mmelite ọ bụla gasịrị, buru ụzọ kpochapụ cache ihe nchọgharị gị — ọ fọrọ obere ka ọ bụrụ ihe kpatara ya mgbe niile.',
'Upd_Restore_Backup_Confirm' => 'Weghachi backup a? Backup ahụ ga-edochi faịlụ ugbu a na database ugbu a. A na-ebu ụzọ were mbipụta nchekwa nke database ugbu a. (v{version} — {date})',
'Woo_Guide_Lead' => 'Otu ụlọ ahịa WooCommerce si na-anọgide na ERP. E wuru ahịrị cron ndị dị n\'okpuru maka sava a, ya mere enwere ike idetuo ha ozugbo n\'elu ya.',
'Woo_Guide_Ways_Note' => 'N\'adịghị ka Shopify, WooCommerce anaghị ezigara ERP ihe ọ bụla n\'onwe ya — ọ dịghị ihe nnata webhook ebe a, ya mere ihe niile na-abata {in} na-eru dịka usoro oge si dị. Ọ bụ naanị ngwaahịa na-apụ {out} nwere ike ịbụ ozugbo.',
'Woo_In' => 'n\'ime',
'Woo_Out' => 'n\'èzí',
'Woo_Guide_Both_Ways_Title' => 'Ụzọ abụọ ahụ chọrọ nke a mbụ',
'Woo_Api_Keys' => 'Igodo API',
'Woo_Guide_Api_Keys_Text' => '{path}, ikike {perm}. Detuo consumer key na secret n\'ime taabụ {settings}, ya na URL ụlọ ahịa — adreesị saịtị gị na-enweghị slash na njedebe, dịka {example}.',
'Woo_Credentials_Saved' => 'e chekwara nzere',
'Woo_Not_Configured_Yet' => 'e hazibeghị ya',
'Woo_Guide_Wp_App_Password_Title' => 'Okwuntughe ngwa WordPress (nhọrọ)',
'Woo_Guide_Wp_App_Password_Text' => 'E ji ya naanị maka onyonyo ngwaahịa. API WooCommerce na-ebugharị ngwaahịa, ngwaahịa dị, ngalaba, akara ngwaahịa, ndị ahịa na ọda; API WordPress bụ ihe na-achọ Media Library ma bulite onyonyo na-adịbeghị ebe ahụ.',
'Woo_Guide_Wp_App_Password_Note' => 'Jiri onye ọrụ WordPress nwere ike ijikwa media, ma mepụta okwuntughe ahụ n\'okpuru {path}. Hapụ mpaghara abụọ ahụ efu, ihe niile ka na-emekọrịta — ọ bụ naanị itinye onyonyo ka a na-awụfe.',
'Woo_Guide_Pick_Way_Title' => 'Wee họrọ otu ọ ga-esi na-anọgide',
'Woo_Right_Away' => 'Ozugbo',
'Woo_Stock_Live' => 'ngwaahịa dị ndụ',
'Woo_Stock_Not_Live' => 'ngwaahịa adịghị ndụ',
'Woo_Guide_Realtime_Lead' => 'Naanị otu ụzọ: ngwaahịa na ngwaahịa dị na-apụ na ERP. Ọda na mgbanwe ngwaahịa e mere na WooCommerce ka na-eru dịka usoro oge si dị — lee taabụ nke ọzọ.',
'Woo_Push_Stock_On_Change' => 'Zipu ngwaahịa dị ozugbo ọ gbanwere',
'Woo_Setting_People_Miss' => 'Nke a bụ ntọala ndị mmadụ na-echefu',
'Woo_Guide_Pos_Sale_Not_Reach' => 'Ire ahịa POS {not} WooCommerce n\'onwe ya. Ọ bụrụ na a hapụ ya gbanyụrụ, ụlọ ahịa ahụ na-achọpụta naanị na mmekọrịta ngwaahịa na-esote — otu awa, dịka ndabara — n\'oge ahụ ọ nwere ike ire nkeji i rerela n\'ụlọ ahịa.',
'Woo_Does_Not' => 'anaghị eru',
'Woo_Guide_Tick_Instant' => 'Kaa {option} na taabụ {settings}. Nke ahụ bụ nhazi niile — enweghị worker, enweghị cron. Ire ahịa ọ bụla, nlọghachi, nhazigharị, mbufe na ịzụta e natara na-ezipu naanị ngwaahịa ndị ahụ, ozugbo e chekwara ire ahịa ahụ, ire ahịa nwere ahịrị iri abụọ na-efu otu nzipu, ọ bụghị iri abụọ. Ụlọ ahịa anaghị eche ya.',
'Woo_Currently' => 'Ugbu a:',
'Woo_Instant_On_Text' => 'gbanyere — a na-ezipu ngwaahịa dị mgbe ọ gbanwere',
'Woo_Instant_Off_Text' => 'gbanyụrụ — ngwaahịa dị naanị dịka usoro oge si dị',
'Woo_Guide_Instant_Note' => 'Ọ bụ naanị ngwaahịa ejikọrịrị na WooCommerce ka a na-ezipu — nke a na-emekọrịtabeghị enweghị ihe n\'ụlọ ahịa a ga-edozi. Ngwaahịa nwere ụdị dị iche iche na-esi na nne ha, a na-ezigharịkwa combo mgbe akụkụ ya ọ bụla gagharịrị. Ọrụ buru ibu (ihichapụ ngwaahịa, ịtọgharị ụlọ nkwakọba ihe) na-ede ngwaahịa dị n\'enweghị ịkpalite ihe omume, nke bụ otu ihe kpatara iji debe mmekọrịta ngwaahịa kwa awa.',
'Woo_Push_Products_On_Save' => 'Zipu ngwaahịa ozugbo e chekwara ha',
'Woo_Guide_Tick_Auto_Products' => 'Kaa {option} na taabụ {settings}, a ga-ezigara WooCommerce ngwaahịa e mepụtara, dezie ma ọ bụ detuo na Stocky ozugbo e chekwara ya — nkọwa, ọnụahịa, ụdị dị iche iche na onyonyo, wee ngwaahịa dị ya. A na-emepụta ngwaahịa ọhụrụ n\'ụlọ ahịa ozugbo kama ichere mmekọrịta ngwaahịa kwa abalị.',
'Woo_On' => 'gbanyere',
'Woo_Off' => 'gbanyụrụ',
'Woo_Guide_Bulk_Imports_Note' => 'A naghị ezipu mbubata buru ibu otu otu — gbaa mmekọrịta ngwaahịa mgbe mbubata gasịrị. Buru ụzọ mekọrịta ngalaba na akara ngwaahịa, ka ngwaahịa e zipụrụ dabara n\'ngalaba ziri ezi.',
'Woo_Nothing_Else_To_Install' => 'Ọ dịghị ihe ọzọ a ga-etinye',
'Woo_Guide_Same_Process' => 'Enweghị queue worker, enweghị ndenye cron. Nzipu ahụ na-agba n\'otu usoro ahụ jere ozi ire ahịa ahụ, {after} nzaghachi ahụ laghachiri, ya mere ụlọ ahịa anaghị eche WooCommerce. Nzipu anaghị agafe ibe ha: mgbanwe e mere mgbe otu na-agba na-eche ya ma pụọ ozugbo ọ gwụsịrị.',
'Woo_After' => 'mgbe',
'Woo_Guide_Shop_Stops_Answering' => 'A na-ahapụ ụlọ ahịa kwụsịrị ịza mgbe sekọnd asatọ gasịrị, nzipu na-akwụsịtụ nkeji ise ka ire ahịa ọ bụla ghara ichere ya ọzọ; mgbanwe batara n\'oge ahụ na-apụ na nzipu mbụ mgbe nkwụsịtụ ahụ gasịrị, mmekọrịta ngwaahịa kwa awa na-ejide n\'agbanyeghị. A na-edekọ nkwụsịtụ ọ bụla na taabụ Ndekọ.',
'Woo_Guide_Artisan_Exception' => 'Otu ewezuga: mgbanwe ngwaahịa e mere site n\'iwu artisan enweghị nzaghachi ọ ga-eso, ya mere a na-etinye ya n\'ahịrị na {queue} kama. Ka ndị ahụ pụọ ngwa ngwa, gbaa ahịrị ahụ:',
'Woo_Cron_Line_Copied' => 'E detuola ahịrị cron',
'Woo_Command_Copied' => 'E detuola iwu',
'Woo_Guide_Not_Woo_Queue' => 'E ji ụma ghara iji queue {queue}: nke ahụ na-ebu batch katalọgụ na-ewe ọtụtụ awa, nzipu ozugbo e tinyere n\'azụ otu agaghị abụ ozugbo.',
'Woo_On_A_Schedule' => 'Dịka usoro oge',
'Woo_Guide_Scheduled_Lead' => 'A na-enyocha ihe niile ọzọ site n\'oge ruo n\'oge, n\'ụzọ abụọ. Nke a bụ otu ọda si eru ERP, otu e si ebipụta katalọgụ, na ihe na-edozi ihe ọ bụla ụzọ ngwa ngwa hapụrụ. Ọrụ ọ bụla nwere ndenye cron nke ya, ya mere ị na-agba naanị ihe ịchọrọ.',
'Woo_Guide_Sync_Drains_Queue' => '{command} na-ekpochapụ ahịrị nke ya mgbe ọ na-agba, ya mere ahịrị ndị a achọghị worker iche. Na Windows, jiri Task Scheduler ya na mmemme {program} na otu arụmụka ahụ, malite na {path}.',
'Woo_Or_No_Cron' => 'Ma ọ bụ enweghị cron ọ bụla',
'Woo_Guide_No_Cron_Text' => 'Taabụ ọ bụla ebe a na-emekọrịta mgbe a chọrọ, mmekọrịta n\'aka na-ekpochapụ batch nke ya mgbe peeji ahụ meghere — ya mere obere ụlọ ahịa nwere ike ịgba n\'enweghị ndenye cron ọ bụla. Ihe ị na-atụfu bụ ihe niile na-eme mgbe ọ dịghị onye na-ele anya: ọda na-eru naanị mgbe mmadụ pịara bọtịnụ ahụ.',
'Woo_Commands_Worth_Knowing' => 'Iwu kwesịrị ịmara',
'Woo_Worth_Knowing' => 'Ihe kwesịrị ịmara',
'Woo_Guide_Changing_Url_Clears' => 'Ịgbanwe URL ụlọ ahịa ma ọ bụ igodo API na-ekpochapụ njikọ ọ bụla — ngwaahịa, ngalaba, akara ngwaahịa na ndị ahịa niile na-emekọrịta ọzọ na ụlọ ahịa ọhụrụ.',
'Woo_Guide_Keep_Skus' => 'Debe SKU ka ha kwekọọ n\'etiti Stocky na WooCommerce: nke ahụ bụ ihe na-egbochi oyiri ma na-eme ka njikọgharị dị mma.',
'Woo_Guide_Stock_Total' => 'Ngwaahịa e bipụtara na Woo bụ {total}, ọ bụghị ọnụọgụ otu ụlọ nkwakọba ihe.',
