'Woo_Settings_Instant_Hint' => 'Ire ahịa, nlọghachi ma ọ bụ nhazigharị na-ezipu ngwaahịa dị maka naanị ngwaahịa ndị ahụ ozugbo e chekwara ya, ya mere ụlọ ahịa na-ezi ezi n\'ime sekọnd kama na mmekọrịta ngwaahịa kwa awa na-esote. Ọ dịghị ihe ọzọ a ga-etinye — nzipu na-agba mgbe e zachara ire ahịa ahụ, ya mere ụlọ ahịa anaghị eche WooCommerce. Ihe ndị ọzọ na taabụ {guide}.',
'Woo_Settings_Instant_Off_Alert' => 'Hapụ ya gbanyụrụ, ire ahịa POS na-eru WooCommerce naanị na mmekọrịta ngwaahịa na-esote — ruo otu awa ka e mesịrị.',
'Woo_Settings_Auto_Products_Hint' => 'A na-ezigara WooCommerce ngwaahịa e mepụtara, dezie ma ọ bụ detuo na Stocky ozugbo e chekwara ya — nkọwa, ọnụahịa, ụdị dị iche iche, onyonyo, wee ngwaahịa dị ya — kama ichere mmekọrịta ngwaahịa. A naghị ezipu mbubata buru ibu; gbaa mmekọrịta ngwaahịa mgbe mbubata gasịrị.',
'Woo_Sync_Tuning' => 'Nhazi mmekọrịta',
'Woo_Sync_Tuning_Intro' => 'Ndabara dabara ọtụtụ ụlọ ahịa. Gbanwee ndị a naanị ma ọ bụrụ na mmekọrịta dị nwayọọ ma ọ bụ oge gwụrụ na hosting gị. A na-ejedebe uru ọ bụla n\'oke dị mma, ikpochapụ mpaghara na-eweghachi ndabara ya.',
'Woo_Setting_This_Up' => 'Ịhazi nke a',
