'Shopify_Stock_Lag_Desc' => 'Ire ahịa n\'ụlọ ahịa na-anọ n\'anya ụlọ ahịa ịntanetị ruo mgbe ahụ — ruo nkeji {n}, ya mere enwere ike ire nkeji ikpeazụ ugboro abụọ n\'ịntanetị. Gbanye {setting}, a ga-ezipu ire ahịa, nlọghachi na nhazigharị ọ bụla n\'ime sekọnd kama.',
