'Shopify_Hook_Note_Register' => 'Ndebanye na-emepụta ndenye aha na Shopify ma tụọ ha aka n\'adreesị a na-akpaghị aka. Etinyela ya n\'aka n\'okpuru Shopify → Settings → Notifications → Webhooks: a na-abinye aka na ndị ahụ site na secret dị iche, a ga-ajụkwa nnyefe ọ bụla.',
