'Shopify_G_Lead_Store' => 'Ihe ụlọ ahịa a chọrọ iji nọgide na-akwekọ. Ihe niile ebe a bụ kpọmkwem maka ụlọ ahịa a — ụzọ na id bụ ezi, ya mere enwere ike idetuo iwu ozugbo n\'elu sava.',
'Shopify_G_Lead_Generic' => 'Otu ụlọ ahịa Shopify si na-anọgide na ERP. Họrọ ụlọ ahịa n\'elu ka ịhụ ọnọdụ ya, ma ọ bụ gụọ ya otu ọ dị — ahịrị cron na webhook URL bụ otu ihe n\'agbanyeghị ụlọ ahịa i jikọrọ.',
'Shopify_G_Ways_Note' => 'Ọtụtụ ụlọ ahịa na-agba ha abụọ: nke mbụ na-eme ka ụlọ ahịa dị ọhụrụ kwa nkeji, nke abụọ na-ejide ihe ọ bụla nke mbụ hapụrụ — webhook na-erughị, mgbanwe e mere ozugbo na nchịkwa Shopify, abalị saịtị ahụ dara.',
'Shopify_G_Both_Need' => 'Ụzọ abụọ ahụ chọrọ nke a mbụ',
'Shopify_G_Credentials' => 'Nzere Shopify',
'Shopify_G_Cred_Intro' => 'Kemgbe Jenụwarị 2026 Shopify anaghịzi emepụta ngwa ahaziri n\'ime nchịkwa, ya mere e nwere ụdị njikọ abụọ:',
'Shopify_G_Cred_DevDash' => '{app} (ụlọ ahịa ọ bụla e jikọrọ ugbu a) — {path}. Nye Admin API scopes maka ihe ụlọ ahịa a na-emekọrịta, tinye ngwa ahụ n\'ụlọ ahịa, wee detuo {clientId} na {clientSecret} site na peeji Settings nke ngwa ahụ n\'ime {where}. ERP n\'onwe ya na-agbanwe ha maka access token ma na-emeghari ya tupu ọ gwụ kwa awa 24. Client secret na-abinyekwa aka na webhook, ya mere achọghị ihe ọzọ. Ngwa ahụ na ụlọ ahịa ahụ ga-anọrịrị n\'otu nzukọ Shopify.',
'Shopify_G_Dev_Dashboard_App' => 'Ngwa Dev Dashboard',
'Shopify_G_Cred_Legacy' => '{app} (e mepụtara na nchịkwa tupu 2026) — ọ na-arụ ọrụ n\'agbanweghị ya na {token} ({prefix}) na {secret} ya dịka secret mbinye aka webhook. Ọ bụghị otu uru ahụ dịka token, ịgbanwe ha n\'ụzọ ezighi ezi bụkarị ihe kpatara a na-ajụ webhook.',
'Shopify_G_Legacy_App' => 'Ngwa ahaziri ochie',
'Shopify_G_API_Secret_Key' => 'API secret key',
'Shopify_G_Stored' => 'echekwara',
'Shopify_G_Missing_Refused' => 'na-efu — a ga-ajụ nnyefe',
'Shopify_G_Where_Data_Desc' => '{path} Ụlọ nkwakọba ihe ERP nke ụlọ ahịa a na-ere ngwaahịa ya, na ọnọdụ Shopify a na-ede ngwaahịa ahụ. Mmekọrịta ngwongwo na mbubata ọda na-ajụ ịgba n\'enweghị ha.',
'Shopify_G_Currently' => 'Ugbu a: ụlọ nkwakọba ihe {warehouse}, ọnọdụ {location}',
'Shopify_G_Not_Set_Lower' => 'e debeghị ya',
'Shopify_G_Ready' => 'dị njikere',
'Shopify_G_Incomplete' => 'ezughị ezu',
'Shopify_G_Manual_Syncs' => 'Mmekọrịta ị na-amalite n\'aka',
'Shopify_G_Manual_Desc' => 'Mmekọrịta a malitere site na {centre} na-aza ozugbo ma na-agba n\'azụ, n\'obere iberibe nke ọ bụla na-aga n\'ihu site n\'ebe nke gara aga kwụsịrị. Hosting na-akwụsị arịrịọ weebụ ogologo (LiteSpeed, nginx, load balancer) anaghị egbutu katalọgụ buru ibu n\'etiti, imechi peeji anaghịkwa akwụsị ya. Worker maka nke ahụ bụ otu ahịrị cron ọzọ:',
'Shopify_G_Cron_Copied' => 'E detuola ahịrị cron',
'Shopify_G_Manual_Note' => 'N\'enweghị ya, mmekọrịta ka na-agwụ, mana naanị mgbe peeji Sync Centre ka meghere: mgbe ọ dịghị worker weere ọgba n\'ime sekọnd ole na ole, peeji ahụ n\'onwe ya na-aga n\'ihu, otu obere arịrịọ n\'otu oge. Na Windows jiri Task Scheduler kwa nkeji: mmemme {program}, arụmụka {args}, malite na {dir}.',
'Shopify_G_Then_Pick' => 'Wee họrọ otu ọ ga-esi na-anọgide',
'Shopify_G_Right_Away' => 'Ozugbo',
'Shopify_G_Stock_Live' => 'ngwaahịa dị ndụ',
'Shopify_G_Stock_Not_Live' => 'ngwaahịa adịghị ndụ',
'Shopify_G_Realtime_Lead' => 'A na-ezipu mgbanwe ọ bụla ka ọ na-eme, n\'ime sekọnd. Akụkụ abụọ, ha bụkwa ngbanwe dị iche: {webhooks} na-ebubata ihe omume ụlọ ahịa n\'onwe ya, {push} na-ezipụkwa ngwaahịa dị.',
'Shopify_G_Webhooks_Lower' => 'webhook',
'Shopify_G_Instant_Push_Lower' => 'nzipu ngwaahịa dị ozugbo',
'Shopify_G_Webhooks_In' => 'Webhook — ụlọ ahịa → ERP',
'Shopify_G_Webhooks_Desc' => 'Ọda, mgbanwe ọnọdụ ọda, na mgbanwe ngwaahịa, onye ahịa na ngwaahịa dị e mere na Shopify. Mepee ụlọ ahịa ma pịa {button} na {tab} ya — ọ dị mma ịpị ya ugboro abụọ. Shopify na-ezipu na:',
'Shopify_G_Webhooks_Tab' => 'taabụ Webhooks',
'Shopify_G_Webhooks_Note' => 'Adreesị ahụ ga-enwerịrị ike iru site n\'ịntanetị site na HTTPS — Shopify agaghị ebunye na {localhost} ma ọ bụ domain {test}. A na-edekọ nnyefe ọ bụla otu ugboro, ya mere ịnwaghachi Shopify apụghị ịmepụta ọda oyiri, enwere ike ịmegharị nke dara. A na-ajụ nnyefe ruo mgbe e chekwara secret mbinye aka sitere na nzọụkwụ 1.',
'Shopify_G_Instant_Out' => 'Nzipu ngwaahịa dị ozugbo — ERP → ụlọ ahịa',
'Shopify_G_Setting_Missed' => 'Nke a bụ ntọala ndị mmadụ na-echefu',
'Shopify_G_Pos_Not_Auto' => 'Ire ahịa POS {not} Shopify n\'onwe ya. Ọ bụrụ na a hapụ ya gbanyụrụ, ụlọ ahịa ahụ na-achọpụta naanị na nzọụkwụ nzipu Ngwongwo na-esote — n\'oge ahụ ọ nwere ike ire nkeji i rerela n\'ụlọ ahịa.',
'Shopify_G_Not' => 'Ọ dịghị mkpa',
'Shopify_G_Tick_Push' => 'Kaa {setting} na {where}. Nke ahụ bụ nhazi niile — enweghị worker, enweghị cron. Ire ahịa, nlọghachi na nhazigharị ọ bụla na-ezipu naanị ngwaahịa ndị ahụ, ozugbo e chekwara ire ahịa ahụ, ire ahịa nwere ahịrị iri abụọ na-efu otu nzipu, ọ bụghị iri abụọ. Ụlọ ahịa anaghị eche ya.',
'Shopify_G_This_Store' => 'Ụlọ ahịa a:',
'Shopify_G_Push_On' => 'gbanyere — a na-ezipu ngwaahịa dị mgbe ọ gbanwere',
'Shopify_G_Push_Off' => 'gbanyụrụ — ngwaahịa dị naanị dịka usoro oge si dị',
'Shopify_G_Push_Note' => 'Ọ bụ naanị ngwaahịa nweelarị njikọ Shopify, na naanị mbugharị n\'ụlọ nkwakọba ihe nke ụlọ ahịa a, ka a na-ezipu. Ọrụ buru ibu — ihichapụ ngwaahịa, ịtọgharị ụlọ nkwakọba ihe — na-ede ngwaahịa dị n\'enweghị ịkpalite ihe omume, nke bụ otu ihe kpatara iji debe nzọụkwụ ngwongwo e haziri.',
'Shopify_G_Nothing_Install' => 'Ọ dịghị ihe ọzọ a ga-etinye',
'Shopify_G_No_Worker_Note' => 'Akụkụ abụọ ahụ achọghị queue worker ma ọ bụ ndenye cron. A na-ejikwa webhook na-abata n\'arịrịọ Shopify mere; nzipu ngwaahịa na-apụ na-agba n\'otu usoro ahụ jere ozi ire ahịa ahụ, {after} nzaghachi ahụ laghachiri — ya mere ụlọ ahịa anaghị eche Shopify, a na-ahapụkwa ụlọ ahịa kwụsịrị ịza mgbe sekọnd iri gasịrị ma hapụ ya maka nzipu ngwongwo e haziri na-esote.',
'Shopify_G_After' => 'mgbe',
'Shopify_G_Artisan_Note' => 'Otu ewezuga: mgbanwe ngwaahịa e mere site n\'iwu artisan enweghị nzaghachi ọ ga-eso, ya mere a na-etinye ya n\'ahịrị na {queue} kama. Ọ bụrụ na ịchọrọ ka ndị ahụ pụọ ngwa ngwa, gbaa ahịrị ahụ:',
'Shopify_G_On_Schedule' => 'Dịka usoro oge',
'Shopify_G_On_Lower' => 'gbanyere',
'Shopify_G_Off_Lower' => 'gbanyụrụ',
'Shopify_G_Scheduled_Lead' => 'A na-enyocha ihe niile ọzọ site n\'oge ruo n\'oge, n\'ụzọ abụọ. Ọ dị nwayọọ karịa oge n\'ezie, mana ọ bụ ihe na-ezipu ngwaahịa dị n\'ụlọ ahịa na-anaghị eji nzipu ozugbo, ihe na-ejide webhook na-efu, na naanị ụzọ e si ebugharị katalọgụ niile.',
'Shopify_G_Cron_Entry' => 'Ndenye cron',
'Shopify_G_Cron_Entry_Desc' => 'Ọ dịghị ihe e haziri na-agba n\'enweghị ya. Otu ahịrị, maka modul a naanị — tinye ya n\'akụkụ ihe ọ bụla ọzọ i họọrọ ịhazi:',
'Shopify_G_Cron_Note' => 'Kwa nkeji ise bụ nkenke kacha mma atụmatụ nwere ike iji, n\'ihi na nkeji ise bụ oge etiti nzọụkwụ kacha nta. Ndenye buru ibu karịa na-aghọ ala — na {example}, nzọụkwụ e debere na nkeji 5 na-agba kwa nkeji 15. Na Windows jiri Task Scheduler: mmemme {program}, arụmụka {args}, malite na {dir}.',
'Shopify_G_Switch_On_Plan' => 'Gbanye ya, ma họrọ atụmatụ',
'Shopify_G_Plan_Desc' => '{where} Ngbanwe ahụ na-ekpebi ma cron nwere ike ime ihe ọ bụla; atụmatụ na-ekpebi ihe ọ na-eme. {step} bụ otu ihe n\'otu ụzọ ya na oge etiti nke ya — {first}, {second}. A na-eji oge etiti ndabara maka nzọụkwụ ọ bụla hapụrụ igbe nke ya efu.',
'Shopify_G_Step_Lower' => 'nzọụkwụ',
'Shopify_G_Plan_Note' => 'Hapụ atụmatụ ahụ efu, ụlọ ahịa ahụ ga-ewepụta ọda ma zipu ngwaahịa dị n\'oge etiti ndabara, nke bụ ihe ọtụtụ ụlọ ahịa chọrọ. Ọda bụ naanị mwepụta: Shopify bụ ebe onye ahịa na-etinye otu.',
'Shopify_G_Schedule_On' => 'usoro oge gbanyere',
'Shopify_G_Schedule_Off' => 'usoro oge gbanyụrụ — naanị n\'aka',
'Shopify_G_When_Step_Runs' => 'Mgbe nzọụkwụ na-agba n\'ezie',
'Shopify_G_When_Note' => 'Nzọụkwụ na-eru mgbe oge kemgbe otu nzọụkwụ ahụ {started} ikpeazụ karịrị oge etiti ya, a gụrụ site n\'akụkọ ọgba. Ya mere mmekọrịta ị malitere n\'aka na-eyigharị nke akpaghị aka na-esote, a na-anwaghachikwa nzọụkwụ na-ada mgbe niile n\'oge etiti ya kama kwa tick. Nchịkọta ụlọ ahịa na-egosi ọgba ikpeazụ nzọụkwụ ọ bụla, oge ọ ga-eru ọzọ, na ihe na-egbochi ya mgbe ọ na-egbochi. Gbaa nzipu katalọgụ mbụ n\'aka — buru ụzọ jiri {dryRun} — tupu itinye ya n\'usoro oge.',
'Shopify_G_Started_Lower' => 'malitere',
'Shopify_G_Where_Setting' => 'Ebe ntọala ọ bụla dị',
'Shopify_G_Where_Setting_Note' => 'Ndị a niile dị n\'ụlọ ahịa dị adị: {path}, wee pensụl (ma ọ bụ {edit} na peeji ụlọ ahịa n\'onwe ya).',
'Shopify_G_Product_Images' => 'Onyonyo ngwaahịa',
'Shopify_G_Img_1' => 'Foto na-apụ ya na ngwaahịa na {push} — onyonyo bụ isi mbụ, wee gallery, wee otu maka ụdị ọ bụla nwere nke ya, ruo iri ise.',
