'Cr_Guide_How_It_Works' => 'Otu o si arụ ọrụ',
'Cr_Guide_Meaning' => 'Ihe ọ pụtara',
'Cr_Guide_T_Statuses' => 'Ọnọdụ',
'Cr_Guide_Statuses_Note' => 'Ọnọdụ na-aga naanị n\'ihu, ya mere mmelite bịara n\'azụ anaghị adọghachi ngwugwu azụ. Ngwugwu e nyelarị ka nwere ike ịkọ na ọ na-alọghachi ma ọ bụ eweghachiri ya.',
'Cr_Guide_S_booked' => 'Courier nwere iwu ahụ; ọ dịbeghị onye bịara were ya. Naanị ugbu a ka enwere ike ịkagbu ndebe.',
'Cr_Guide_S_picked_up' => 'Courier ewerela ngwugwu ahụ.',
'Cr_Guide_S_in_transit' => 'Na-aga n\'etiti ebe nchekwa, nọ na kọstọm ma ọ bụ ejidere ya.',
'Cr_Guide_S_out_for_delivery' => 'Nọ n\'aka onye na-ebuga ya taa.',
'Cr_Guide_S_failed_attempt' => 'Ọ nọghị n\'ụlọ, ọ jụrụ ma ọ bụ adreesị ezighi ezi. Courier na-anwa ọzọ ma ọ bụ weghachi ya.',
'Cr_Guide_S_delivered' => 'E nyela onye ahịa ya. Ego COD na-aghọ nke courier natara.',
'Cr_Guide_S_returning' => 'Na-alọghachikwute gị.',
'Cr_Guide_S_returned' => 'Alọghachila n\'aka gị: ọ na-eche na Nloghachi a ga-enyocha, ma ọ bụ a na-etinyeghachi ya na ngwaahịa na-akpaghị aka.',
'Cr_Guide_S_cancelled' => 'Akagbuola ndebe ahụ.',
'Cr_Guide_T_Booking' => 'Ndebe iwu',
'Cr_Guide_B_Booking' => 'Ziga na courier na-ejupụta fọm ahụ site na ọrịre: onye nnata, adreesị, ego fọdụrụ dịka COD, na ịdị arọ nke ngwaahịa. Ndị courier nwere ndepụta obodo nke ha na-egosi ihe nhọrọ, a na-echetakwa nhọrọ gị maka obodo ahụ. Ndị aggregator, DHL, FedEx, UPS na Lalamove na-enye Tụnyere ọnụahịa: họrọ ọnụahịa ma Debe na-azụta ya. Enwere ike idebe ọtụtụ ọrịre otu mgbe site na ndepụta ọrịre.',
'Cr_Guide_T_Cod' => 'Ịkwụ ụgwọ mgbe e nyere',
'Cr_Guide_B_Cod' => 'Ngwugwu COD na-esi na Anatabeghị gaa na Courier anatala (mgbe e nyere) gaa na Akwụọla gị. Ndị courier na-akọ ịkwụ ego na-eme nzọụkwụ ikpeazụ n\'onwe ha; maka ndị ọzọ jiri Melite COD. Ọ bụrụ na a họrọ akaụntụ na Ntọala Courier, a na-edekọ ịkwụ ego dịka ịkwụ ụgwọ na ọrịre. Enwere ike ịchekwa ụgwọ courier dịka mmefu ego ozugbo ngwugwu gwụchara.',
'Cr_Guide_T_Returns' => 'Ngwugwu eweghachiri',
'Cr_Guide_B_Returns' => 'Dịka ndabara, ngwugwu eweghachiri na-eche na Mbupu Courier n\'okpuru Nloghachi a ga-enyocha. Tinyeghachi na ngwaahịa na-emepụta nloghachi ọrịre maka iwu ahụ niile ma tinyeghachi ihe ndị ahụ na ngwaahịa dị; Hapụ anaghị etinyeghachi ihe ọ bụla, maka ngwugwu mebiri emebi ma ọ bụ furu efu. Ntọala Courier nwere ike itinyeghachi na ngwaahịa na-akpaghị aka kama.',
'Cr_Guide_T_Customers' => 'Ozi ndị ahịa na ibe nsochi',
'Cr_Guide_B_Customers' => 'Ọkwa ndị ahịa na Ntọala Courier na-eziga SMS, email ma ọ bụ WhatsApp n\'ọnọdụ ị kara akara, otu ugboro kwa ngwugwu, na ederede nke gị. Ibe nsochi n\'ụlọ ahịa ịntanetị gị na-ekwe ka ndị ahịa soro ngwugwu site na nọmba nsochi, ma ọ bụ site na nọmba iwu na ekwentị. Ndị ahịa na-eweghachikarị ngwugwu na-enweta akara ihe ize ndụ nloghachi mgbe ị na-edebe.',
'Cr_Guide_T_Labels' => 'Label',
'Cr_Guide_B_Labels' => 'Bipụta label na-enye label nke courier mgbe ọ na-ewepụta otu (PDF, njikọ ma ọ bụ foto), ma ọ bụghị ya label Stocky nwere barcode nsochi na ego a ga-anata. Kwe ka pop-up rụọ ọrụ na saịtị a iji bipụta. DHL, FedEx na UPS na-enye label ha naanị otu ugboro, mgbe a na-edebe, Stocky na-edebekwa ya maka mbipụta ọzọ.',
'Cr_Guide_T_Faq' => 'Idozi nsogbu',
'Cr_Guide_Q_Test' => 'Nwalee njikọ na-ada',
'Cr_Guide_A_Test' => 'Igodo nnwale na-aga na Ọnọdụ nnwale, igodo ndụ na-agakwa na Ndụ; ha dị iche. Mepee Ndekọ courier ma gụọ azịza courier iji mara ezigbo ihe kpatara ya.',
'Cr_Guide_Q_City' => 'Courier na-ajụ obodo ma ọ bụ adreesị',
'Cr_Guide_A_City' => 'Họrọ obodo site na ndepụta obodo courier na fọm ndebe; ndị courier na-anabata naanị aha nke ha. Ndị courier na-arụ ọrụ na adreesị nzipu ozi chọkwara steeti, koodu nzipu ozi na mkpụrụedemede abụọ nke mba.',
'Cr_Guide_Q_Webhook' => 'Ọnọdụ anaghị agbanwe n\'onwe ha',
'Cr_Guide_A_Webhook' => 'Maka ndị courier na-ezite mmelite, lelee na edebanyere webhook URL n\'aka courier: Ndekọ courier na-egosi mmelite ọ bụla e natara, ma ọ bụ ihe mere a jụrụ otu (dịka ọmụmaatụ ihe nzuzo ezighi ezi). A na-enyocha ndị courier ọzọ n\'usoro oge dị na Ntọala Courier, Lelee ọnọdụ ugbu a na-ajụkwa ozugbo.',
'Cr_Guide_Q_Stuck' => 'Mbupu na-egosi njehie nlele ọnọdụ',
'Cr_Guide_A_Stuck' => 'Courier jụrụ nlele ikpeazụ; ihe kpatara ya dị na mbupu ahụ na na Ndekọ courier. Mgbe ọdịda ugboro ugboro gasịrị, a naghị enyocha mbupu ahụ na-akpaghị aka ọzọ: dozie ihe kpatara ya, wee jiri Lelee ọnọdụ ugbu a.',
'Cr_Guide_Q_Label' => 'Ọ dịghị ihe na-emepe mgbe a na-ebipụta label',
'Cr_Guide_A_Label' => 'Ihe nchọgharị gị gbochiri pop-up ahụ. Kwe ka pop-up rụọ ọrụ na saịtị a ma nwaa ọzọ.',
'Cr_Guide_Q_Cod' => 'Edekọghị ego COD a kwụrụ na ọrịre',
'Cr_Guide_A_Cod' => 'Na Ntọala Courier, ịkwụ ụgwọ mgbe e nyere chọrọ ka a gbanye mgba ọkụ ya ma họrọ akaụntụ. Na-enweghị akaụntụ, a na-akara naanị ego a kwụrụ dịka akwụọla.',
