'Tfa_Done' => 'Emechaala',
'Tfa_Codes_Save' => 'Chekwaa koodu mgbake ndị a n\'ebe dị nchebe. Nke ọ bụla na-abanye gị otu ugboro ma ọ bụrụ na ekwentị gị efuo. A gaghị egosi ha ọzọ.',
'Tfa_Reset' => 'Tọgharịa ihu abụọ',
'Tfa_Reset_Title' => 'Tọgharịa nkwenye ihu abụọ?',
'Tfa_Reset_Help' => ':name ga-abanye naanị site na paswọọdụ ya ma nwee ike ịhazi ngwa authenticator ya ọzọ. Mee nke a naanị mgbe ị kwadoro onye na-arịọ.',
'Tfa_Guide_Lead' => 'Nkwenye ihu abụọ (2FA) na-agbakwunye nzọụkwụ nke abụọ n\'ịbanye: mgbe paswọọdụ gasịrị, ndị ọrụ na-apịnye koodu ọnụọgụ 6 sitere na ngwa authenticator dị na ekwentị ha. Paswọọdụ ezuru ezu ma ọ bụ nke e chere echiche ezughịzi ịbanye.',
