'Tfa_Guide_App_Title' => 'Wụnye ngwa authenticator',
'Tfa_Guide_App_Text' => 'Ngwa ọ bụla na-akwado koodu ọnụọgụ 6 nkịtị (TOTP) na-arụ ọrụ. Ha bụ n\'efu ma na-arụ ọrụ na-enweghị ịntanetị:',
'Tfa_Guide_Enable_Title' => 'Gbanwuo ya site na profaịlụ',
'Tfa_Guide_Enable_1' => 'Mepee Profaịlụ (menu avatar dị n\'elu aka nri) ma chọta kaadị "Nkwenye ihu abụọ".',
'Tfa_Guide_Enable_2' => 'Pịa "Gbanwuo" ma kwado ya site na paswọọdụ dị ugbu a.',
'Tfa_Guide_Enable_3' => 'Jiri ngwa ahụ nyochaa koodu QR, ma ọ bụ pịnye igodo egosiri n\'okpuru ya.',
'Tfa_Guide_Enable_4' => 'Tinye koodu ọnụọgụ 6 ngwa ahụ gosiri ka imecha.',
'Tfa_Guide_Open_Profile' => 'Mepee profaịlụ m',
'Tfa_Guide_Codes_Title' => 'Chekwaa koodu mgbake',
'Tfa_Guide_Codes_Text' => 'Ozugbo nhazi gachara, a na-egosi koodu mgbake 8 otu ugboro. Nke ọ bụla na-edochi koodu ekwentị otu ugboro — maka ekwentị furu efu, mebiri emebi ma ọ bụ e tọgharịrị. Budata ma ọ bụ detuo ha ma debe ha n\'ebe dị nchebe, n\'ebe dị anya na ekwentị.',
'Tfa_Guide_Codes_Note' => 'Ha na-agwụ? "Koodu mgbake ọhụrụ" na profaịlụ na-edochi otu ha niile; ndị ochie na-akwụsị ịrụ ọrụ.',
'Tfa_Guide_Signin_Title' => 'Ịbanye',
'Tfa_Guide_Signin_Text' => 'Mgbe Email na paswọọdụ gasịrị, peeji ịbanye na-arịọ koodu dị ugbu a sitere na ngwa ahụ. Koodu na-agbanwe kwa sekọnd 30 ma nke ọ bụla na-arụ ọrụ otu ugboro.',
'Tfa_Guide_Signin_Trust' => 'Ịkara "Ajụkwala ọzọ na ngwaọrụ a" na-amafe koodu na browser ahụ ruo ụbọchị :days.',
'Tfa_Guide_Signin_Recovery' => 'Ekwentị adịghị n\'aka? Pịa "Jiri koodu mgbake" ma pịnye otu n\'ime koodu echekwara.',
'Tfa_Guide_Admin_Title' => 'Maka ndị nchịkwa',
'Tfa_Guide_Require_Title' => 'Mee ka ọ bụrụ iwu',
'Tfa_Guide_Require_Text' => 'Gbanwuo "Mee ka nkwenye ihu abụọ bụrụ iwu" na kaadị a, wee họrọ ọrụ ndị ga-eji ya — ma ọ bụ hapụ ndepụta ahụ efu maka onye ọrụ ọ bụla. Pịa Zipu ka ichekwa.',
'Tfa_Guide_Require_Next' => 'A naghị ewepụ onye ọ bụla. Ndị ọrụ na-enwebeghị 2FA ka a ga-edu site na nhazi na peeji ịbanye mgbe ha banyere ọzọ, tupu ha abanye, ma ha ga-ahụ koodu mgbake ha n\'ebe ahụ.',
'Tfa_Guide_Require_Note' => 'Ndị ọrụ a chọrọ ya maka ha enweghị ike ịgbanyụ ya site na profaịlụ ha.',
'Tfa_Guide_Trust_Title' => 'Ngwaọrụ a tụkwasịrị obi',
'Tfa_Guide_Trust_Text' => '"Cheta ngwaọrụ a tụkwasịrị obi" na-atọ ogologo oge browser nwere ike ịmafe koodu mgbe ịbanye gara nke ọma. Họrọ "Na-arịọ koodu mgbe niile" maka kọmputa a na-ekerịta ma ọ bụ nke ọha dị ka POS dị n\'ime ụlọ ahịa.',
'Tfa_Guide_Trust_Note' => 'Ibelata ọnụọgụ ahụ na-ebelata ngwaọrụ a tụkwasịrịlarị obi; ịgbanyụ 2FA ma ọ bụ ịtọgharị ya na-echefu ha niile.',
'Tfa_Guide_Lost_Title' => 'Ekwentị furu efu na enweghị koodu mgbake',
'Tfa_Guide_Lost_Text' => 'Na peeji Ndị Ọrụ, ndị ọrụ nwere 2FA na-egosi "Gbanwụrụ" na kọlụm 2FA. Bọtịnụ ọta dị na Omume na-atọgharị ya: onye ọrụ ahụ na-abanye naanị site na paswọọdụ ma hazie ngwa ahụ ọzọ (ma ọ bụ a ga-arịọ ya, ma ọ bụrụ na ọ bụ iwu).',
'Tfa_Guide_Lost_Warn' => 'Kwado onye na-arịọ tupu ịtọgharị — ịtọgharị na-ewepụ nchebe 2FA na-enye akaụntụ ahụ.',
'Tfa_Guide_Open_Users' => 'Mepee Ndị Ọrụ',
'Tfa_Guide_Mobile_Title' => 'Ngwa ekwentị na API',
'Tfa_Guide_Mobile_Text' => 'Ngwa ekwentị na njedebe token API na-arịọ otu koodu ahụ. Ọ bụrụ na 2FA bụ iwu maka onye ọrụ na-ahazibeghị ya, ọ ga-abanye na weebụ otu ugboro iji mee ya.',
'Tfa_Guide_Protect_Title' => 'Nchebe arụnyere n\'ime',
'Tfa_Guide_Protect_1' => 'Koodu 5 ezighị ezi na-egbochi itinye koodu maka onye ọrụ ahụ ruo nkeji 15, n\'agbanyeghị ntọala mkpọchi dị n\'elu.',
'Tfa_Guide_Protect_2' => 'Koodu ọ bụla na koodu mgbake ọ bụla na-arụ ọrụ naanị otu ugboro.',
'Tfa_Guide_Protect_3' => 'Mgbe "Dekọọ ọrụ ịbanye" gbanwụrụ, koodu ezighị ezi na-apụta na ndepụta ọrụ ịbanye dị ka "Koodu 2FA ezighị ezi".',
'Tfa_Guide_Trouble_Title' => 'Idozi nsogbu',
'Tfa_Guide_Faq_Clock_Q' => '“Koodu ahụ ezighị ezi” n\'agbanyeghị na koodu ahụ dị ọhụrụ',
'Tfa_Guide_Faq_Clock_A' => 'Elekere ekwentị nwere ike ọ gaghị eziokwu. Koodu na-adabere n\'oge: tọọ ụbọchị na oge ekwentị ka ọ bụrụ akpaghị aka (oge netwọk), wee nwaa koodu na-esote.',
'Tfa_Guide_Faq_Phone_Q' => 'Ịkwaga na ekwentị ọhụrụ',
'Tfa_Guide_Faq_Phone_A' => 'Ma ọ bụ jiri njirimara mbufe nke ngwa authenticator ahụ, ma ọ bụ gbanyụọ 2FA na profaịlụ wee gbanwuo ya ọzọ site na ekwentị ọhụrụ (ọ bụrụ na ọ bụ iwu, rịọ onye nchịkwa ka ọ tọgharịa ya kama).',
'Tfa_Guide_Faq_Locked_Q' => '“Koodu ezighị ezi dị ukwuu”',
'Tfa_Guide_Faq_Locked_A' => 'Chere oge egosiri (ruo nkeji 15), ma ọ bụ mee ka onye nchịkwa tọgharịa 2FA onye ọrụ ahụ.',
'Tfa_Guide_Faq_Key_Q' => 'Ọ dịghị onye nwere 2FA nwere ike ịbanye mgbe a kwagara sava',
'Tfa_Guide_Faq_Key_A' => 'A na-ezo ihe nzuzo 2FA site na APP_KEY dị na faịlụ .env. Debe otu APP_KEY ahụ mgbe ị na-akwaga ma ọ bụ na-eweghachi ngwa ahụ; ọ bụrụ na ọ gbanwere, onye nchịkwa na-enweghị 2FA ga-atọgharị ndị ọrụ metụtara.',
'Tfa_Guide_Button' => 'Ntuziaka',
'Tfa_Guide_Title' => 'Ntuziaka nkwenye ihu abụọ',
'Sec_2fa_Pending' => ':count ka ga-ahazi ya',
'Sec_2fa_See_Who' => 'Hụ ndị ọ bụ',
'Sec_2fa_Grace_Off' => 'Ọ dịghị — hazie ya mgbe ịbanye ọzọ',
'Sec_2fa_Applied' => 'Ewepụla onye ọrụ :count.',
'Tfa_Guide_Rollout_Title' => 'Mee ka ọ ruo onye ọrụ ọ bụla',
'Tfa_Guide_Rollout_1' => 'Buru ụzọ gbanwuo ya maka akaụntụ gị (Profaịlụ), ka ị mara nzọụkwụ ndị ahụ.',
'Tfa_Guide_Rollout_2' => 'Gwa otu gị ngwa ha ga-awụnye na nhazi na-ewe otu nkeji mgbe ha na-abanye.',
'Tfa_Guide_Rollout_3' => 'Gbanwuo "Mee ka nkwenye ihu abụọ bụrụ iwu", hapụ "Achọrọ maka" efu (= onye ọrụ ọ bụla), ma họrọ oge ntachi obi ma ọ masịrị gị. Pịa Zipu.',
'Tfa_Guide_Rollout_4' => 'Pịa "Wepụ ndị ọrụ na-enweghị 2FA" ka ndị banyelarị hazie ya ugbu a kama ịhazi ya n\'ịbanye ọzọ n\'ọdịnihu. Ị ga-anọgide n\'ime.',
'Tfa_Guide_Rollout_5' => 'Soro ọganihu site na ngụkọ dị na kaadị a, ma ọ bụ nzacha "Chọrọ nhazi" na peeji Ndị Ọrụ.',
'Tfa_Guide_Rollout_Note' => 'Site n\'oge ntachi obi, ihuenyo nhazi na-egosi “Cheteara m ma emechaa” ruo mgbe oge ahụ gwụrụ; mgbe ahụ gasịrị, nhazi bụ iwu iji banye.',
'Tfa_Guide_Customers_Title' => 'Akaụntụ ndị ahịa (ụlọ ahịa na Portal ndị ahịa)',
'Tfa_Guide_Customers_Text' => 'Ndị ahịa nwekwara ike ichebe akaụntụ nke ha. Ọ bụ nhọrọ maka onye ahịa ọ bụla, a naghị amanye ya: gbanwuo ya n\'okpuru Ntọala Ụlọ Ahịa → Njikwa Nnweta Ndebanye (ụlọ ahịa n\'ịntanetị) na Portal Ndị Ahịa → Ntọala Portal (Portal ndị ahịa).',
'Tfa_Guide_Customers_1' => 'Ndị ahịa na-agbanwu ya site na Akaụntụ M (ụlọ ahịa) ma ọ bụ Profaịlụ (Portal).',
'Tfa_Guide_Customers_2' => 'Ha na-ahọrọ koodu ezigara site na Email — nke kacha dị mfe, enweghị ngwa achọrọ — ma ọ bụ ngwa authenticator nwere koodu mgbake.',
'Tfa_Guide_Customers_3' => 'Koodu ezigara site na Email chọrọ ntọala mail na-arụ ọrụ (Ntọala → Ntọala Mail). Ha na-agwụ mgbe nkeji 10 gachara.',
'Tfa_Guide_Customers_4' => 'Ịgbanyụ nhọrọ ahụ ma emechaa na-akwụsị nhazi ọhụrụ; ndị ahịa na-eji ya ugbu a ka a ga-anọgide na-arịọ ma ha nwere ike ịgbanyụ ya n\'onwe ha.',
'Tfa_Required_Grace_Notice' => 'Onye nchịkwa gị chọrọ nkwenye ihu abụọ. Ị nwere ike ịyigharị ya mgbe ị na-abanye ruo :date; mgbe ahụ gasịrị, nhazi bụ iwu.',
'Tfa_Filter_All' => '2FA: ndị ọrụ niile',
'Tfa_Needs_Setup_Help' => 'Ntọala Sistemụ > Nchekwa chọrọ ya; a ga-arịọ ka ọ hazie ya mgbe ọ banyere ọzọ.',
